<?php $currentFilter=$_GET;unset($currentFilter['page']); ?>
<?php if($savedFilters||array_filter($currentFilter)):?><div class="saved-filter-bar"><span><i class="fa-regular fa-bookmark"></i> Saved views</span><?php foreach($savedFilters as $filter):$query=json_decode($filter['filter_json'],true)?:[];?><a href="<?= url($entity).'?'.http_build_query($query) ?>"><?= e($filter['name']) ?></a><form method="post" action="<?= url($entity.'/filters/'.$filter['id'].'/delete') ?>"><?= csrf_field() ?><button title="Delete saved view"><i class="fa-solid fa-xmark"></i></button></form><?php endforeach;?><?php if(array_filter($currentFilter)):?><form class="save-filter-form" method="post" action="<?= url($entity.'/filters') ?>"><?= csrf_field() ?><input name="name" required maxlength="100" placeholder="Name this view"><input type="hidden" name="query" value="<?= e(http_build_query($currentFilter)) ?>"><button class="button button-secondary button-sm">Save current view</button></form><?php endif;?></div><?php endif;?>
